export const SEASON_2026_MATCHES: readonly Match[] = ROWS.map((row, index) => ({
  id: `2026-${String(index + 1).padStart(3, '0')}`,
  competition: row.competition,
  stage: row.stage ?? 'regular',
  date: row.date,
  time: row.time,
  venue: row.venue,
  homeTeamId: row.home,
  awayTeamId: row.away,
  score: row.goals
    ? {
        home: row.goals[0],
        away: row.goals[1],
        resolution: row.resolution ?? 'regulation',
      }
    : null,
  notes: null,
}))

